// Menuiseries vendues au « point » (book de tarifs 2026). Le prix € du point est
// réglable dans l'outil de chiffrage (valeur commerciale, non fournie par le book).
// Données extraites des grilles (hauteur × largeur) du PDF « BOOK TARIF NEW ».
// p = points selon (hauteur, largeur) ; null = combinaison hors grille du tarif.
// Pour les portes de garage, les dimensions sont des plages (ex. 2001-2100) :
// v = milieu de plage pour le calcul, l = libellé affiché.
export type Dim = { v: number; l?: string };
export type LigneGrille = { d: Dim; m?: string; p: (number | null)[] };
export type GrilleMenuiserie = {
  id: string;
  nom: string;
  categorie: string;
  tva: 0.055 | 0.1;
  cols: Dim[];
  lignes: LigneGrille[];
};

